19	func writeHostedFactsBinding(brainDir, branch, repoID, baseURL string) error {
20		binding := hostedFactsBinding{RepoID: repoID, BaseURL: strings.TrimRight(baseURL, "/")}
21		data, err := json.Marshal(binding)
