56	// TestStatusReportsDeclaredDocsIndexMissing is the honesty contract: when the
57	// manifest declares a docs index that is no longer on disk, retrieval silently
58	// drops the entire docs layer (loadDocIndex's os.IsNotExist is skipped, not
59	// raised), so status/brain_status must not keep reporting "docs: ok" and a
60	// freshness severity of "ok". A caller cannot otherwise tell a dead docs layer
61	// apart from "nothing matched".
62	func TestStatusReportsDeclaredDocsIndexMissing(t *testing.T) {
63		opts, repoDir, brainDir := docsAvailabilityFixture(t)
64	
65		healthy, err := buildAvailableBrainStatusReport(context.Background(), opts, repoDir)
66		if err != nil {
67			t.Fatalf("healthy status: %v", err)
68		}
69		if healthy.Retrieval == nil || healthy.Retrieval.Freshness == nil {
70			t.Fatalf("healthy status has no retrieval freshness: %+v", healthy.Retrieval)
71		}
72		if got := healthy.Retrieval.Freshness.Axes["docs"].State; got != "ok" {
73			t.Fatalf("healthy docs axis = %q, want ok (%+v)", got, healthy.Retrieval.Freshness.Axes["docs"])
74		}
75		if got := healthy.Retrieval.Freshness.Severity; got != "ok" {
76			t.Fatalf("healthy retrieval severity = %q, want ok", got)
77		}
